using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int W;
    cin >> W;
    vector<int> a(W);
    for (int i = 0; i < W; i++) {
        cin >> a[i];
    }

    const int MAX_TIME = 20000; // safe upper bound
    vector<vector<long long>> dp(2, vector<long long>(W, 0));

    // Initialize time 0: people from entrances appear now but move at t+1
    for (int i = 0; i < W; i++) {
        if (a[i] > 0) {
            dp[0][i] = a[i];
        }
    }

    long long ans = 0;

    for (int t = 0; t < MAX_TIME; t++) {
        int cur = t % 2;
        int nxt = 1 - cur;
        fill(dp[nxt].begin(), dp[nxt].end(), 0);

        for (int i = 0; i < W; i++) {
            if (dp[cur][i] == 0) continue;

            // check fire block: if a[i] < 0 and |a[i]| <= t, blocked
            if (a[i] < 0 && -a[i] <= t) continue;

            // Exit reached
            if (a[i] == 0) {
                ans += dp[cur][i];
                continue;
            }

            // Move to neighbors and stay
            if (i > 0) dp[nxt][i-1] += dp[cur][i];
            dp[nxt][i] += dp[cur][i];
            if (i + 1 < W) dp[nxt][i+1] += dp[cur][i];
        }

        // No more people moving
        bool any = false;
        for (int i = 0; i < W; i++) if (dp[nxt][i] > 0) { any = true; break; }
        if (!any) break;
    }

    cout << ans << "\n";
    return 0;
}

