using int64 = long long;
const long long INF = (1LL << 60);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int W;
    cin >> W;
    vector<long long> a(W);
    for (int i = 0; i < W; ++i) cin >> a[i];

    // exits
    vector<int> exits;
    for (int i = 0; i < W; ++i) {
        if (a[i] == 0) exits.push_back(i);
    }

    // If there is no exit, nobody can escape.
    if (exits.empty()) {
        cout << 0 << '\n';
        return 0;
    }

    // For each cell i, compute the maximum time T[i] such that a person may be in i at time t only if t < T[i].
    // Fire door at j with value -f blocks cell j from time f onward, so to pass through j at time t we need t < f.
    // Therefore for any path from i to an exit e, all cells on the path must satisfy t_at_cell < fire_time.
    // This yields:
    // feasible iff there exists exit e such that arrival time d=|i-e| and for every fire door j between i and e:
    // d - dist(i,j) < fire_time(j)
    // which transforms to a bound on departure/start time s:
    // s < fire_time(j) - dist(j,e) if j lies on path.
    //
    // For a fixed exit e and side, the best allowable start time is the minimum of (fire_time(j)-dist(j,e))
    // over fire doors j on that segment; then from i one can escape if start time s satisfies
    // s + |i-e| < that minimum.
    //
    // We compute for each cell i the best value of:
    // T[i] = max over exits e reachable from i of ( min_fire_on_segment_to_e (fire_time - dist_to_e) - dist(i,e) )
    // Then people generated at times t=0..a[i]-1 start moving at times s=t+1, and can escape iff s < T[i].
    // Count = number of s in [1..a[i]] with s < T[i] = clamp(min(a[i], T[i]-1), >=0)

    vector<long long> best(W, -INF);

    // Sweep from left to right for exits on the left.
    // Maintain cur = max over exits e seen so far of (min fire bound on segment from current position back to e) - dist(current,e))
    // More conveniently, for each active exit e, its value decreases by 1 each step right,
    // and when crossing a fire door at position k with fire time f, all active paths are capped by f-1 at cell k+1 effect.
    //
    // Equivalent DP:
    // At position i, let dp be best T[i] using an exit at or left of i.
    // Transition:
    // - if cell i is an exit, can start there and stay: effectively infinite before considering future fires.
    // - moving one step right decreases T by 1
    // - if cell i is a fire door with fire time f, then to be at i at time t we need t < f,
    //   so any path crossing i from left to right imposes T[i] <= f, and thus for next cell T[next] <= f-1.
    //
    // Implement directly:
    long long dp = -INF;
    for (int i = 0; i < W; ++i) {
        if (a[i] == 0) dp = INF;              // exit at i
        if (a[i] < 0) dp = min(dp, -a[i]);    // being at i requires time < fire_time
        best[i] = max(best[i], dp);
        if (dp > -INF/2) dp -= 1;             // move to i+1
    }

    // Sweep from right to left for exits on the right.
    dp = -INF;
    for (int i = W - 1; i >= 0; --i) {
        if (a[i] == 0) dp = INF;
        if (a[i] < 0) dp = min(dp, -a[i]);
        best[i] = max(best[i], dp);
        if (dp > -INF/2) dp -= 1;
    }

    long long ans = 0;
    for (int i = 0; i < W; ++i) {
        if (a[i] > 0) {
            // Starts at times s = 1..a[i], escapable iff s < best[i]
            long long cnt;
            if (best[i] <= 1) cnt = 0;
            else if (best[i] >= INF / 2) cnt = a[i];
            else cnt = min<long long>(a[i], best[i] - 1);
            ans += cnt;
        }
    }

    cout << ans << '\n';
    return 0;
}

