def solve():
    input_data = sys.stdin.read().split()
    W = int(input_data[0])
    a = list(map(int, input_data[1:W+1]))

    T_max = W + max(abs(x) for x in a) + 10

    # accessible(unit, time): unit is not a fire door, or time < |a_unit|
    def accessible(u, t):
        if u < 0 or u >= W:
            return False
        if a[u] < 0:
            return t < abs(a[u])
        return True  # exit or entrance

    # DP: can_reach[u][t] = True if person at unit u at time t can reach exit
    # We work backwards from large T
    can_reach = [[False] * (T_max + 2) for _ in range(W)]

    # Base: exit doors
    for u in range(W):
        if a[u] == 0:
            for t in range(T_max + 1):
                can_reach[u][t] = True

    # Backwards DP
    for t in range(T_max - 1, -1, -1):
        for u in range(W):
            if not accessible(u, t):
                continue
            if can_reach[u][t]:
                continue
            # Try moving to neighbors at t+1
            for nu in [u-1, u, u+1]:
                if accessible(nu, t+1) and can_reach[nu][t+1]:
                    can_reach[u][t] = True
                    break

    # Count people who can reach exit
    count = 0
    for u in range(W):
        if a[u] > 0:
            for t in range(a[u]):
                if accessible(u, t) and can_reach[u][t]:
                    count += 1

    print(count)

