import java.util.*;

public class Solution {
    static class Dinic {
        class Edge {
            int to, rev;
            long cap;
            Edge(int to, int rev, long cap) {
                this.to = to;
                this.rev = rev;
                this.cap = cap;
            }
        }

        List<Edge>[] graph;
        int[] level, iter;

        Dinic(int n) {
            graph = new ArrayList[n];
            for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
            level = new int[n];
            iter = new int[n];
        }

        void addEdge(int from, int to, long cap) {
            graph[from].add(new Edge(to, graph[to].size(), cap));
            graph[to].add(new Edge(from, graph[from].size() - 1, 0));
        }

        void bfs(int s) {
            Arrays.fill(level, -1);
            Queue<Integer> q = new LinkedList<>();
            level[s] = 0;
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (Edge e : graph[v]) {
                    if (e.cap > 0 && level[e.to] < 0) {
                        level[e.to] = level[v] + 1;
                        q.add(e.to);
                    }
                }
            }
        }

        long dfs(int v, int t, long f) {
            if (v == t) return f;
            for (int i = iter[v]; i < graph[v].size(); i++) {
                Edge e = graph[v].get(i);
                if (e.cap > 0 && level[v] < level[e.to]) {
                    long d = dfs(e.to, t, Math.min(f, e.cap));
                    if (d > 0) {
                        e.cap -= d;
                        graph[e.to].get(e.rev).cap += d;
                        return d;
                    }
                }
                iter[v]++;
            }
            return 0;
        }

        long maxFlow(int s, int t) {
            long flow = 0;
            while (true) {
                bfs(s);
                if (level[t] < 0) return flow;
                Arrays.fill(iter, 0);
                long f;
                while ((f = dfs(s, t, Long.MAX_VALUE)) > 0) {
                    flow += f;
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int W = sc.nextInt();
        int[] a = new int[W];
        for (int i = 0; i < W; i++) {
            a[i] = sc.nextInt();
        }

        // Determine max time needed
        int maxGen = 0;
        int maxBlock = 0;
        for (int i = 0; i < W; i++) {
            if (a[i] > 0) maxGen = Math.max(maxGen, a[i]);
            if (a[i] < 0) maxBlock = Math.max(maxBlock, -a[i]);
        }

        // Maximum time steps needed: max generation + W (to reach any exit)
        int maxTime = maxGen + W + 2;
        // Also need to consider block times
        maxTime = Math.max(maxTime, maxBlock + 2);
        maxTime = Math.min(maxTime, 200); // safety limit

        // Each node: unit * (maxTime+1) + time
        int nodes = W * (maxTime + 1) + 2;
        int source = nodes - 2;
        int sink = nodes - 1;

        Dinic dinic = new Dinic(nodes);

        // For each unit and time
        for (int i = 0; i < W; i++) {
            for (int t = 0; t <= maxTime; t++) {
                int node = i * (maxTime + 1) + t;

                // Check if fire door blocks at this time
                if (a[i] < 0 && t >= -a[i]) {
                    continue; // blocked, no edges from here
                }

                // If exit door, connect to sink
                if (a[i] == 0) {
                    dinic.addEdge(node, sink, Long.MAX_VALUE / 2);
                    continue;
                }

                // Move to next time step
                if (t < maxTime) {
                    // Stay
                    int nextNode = i * (maxTime + 1) + (t + 1);
                    boolean blocked = (a[i] < 0 && t + 1 >= -a[i]);
                    if (!blocked) {
                        dinic.addEdge(node, nextNode, Long.MAX_VALUE / 2);
                    }

                    // Move left
                    if (i > 0) {
                        int leftNode = (i - 1) * (maxTime + 1) + (t + 1);
                        boolean leftBlocked = (a[i-1] < 0 && t + 1 >= -a[i-1]);
                        if (!leftBlocked) {
                            dinic.addEdge(node, leftNode, Long.MAX_VALUE / 2);
                        }
                    }

                    // Move right
                    if (i < W - 1) {
                        int rightNode = (i + 1) * (maxTime + 1) + (t + 1);
                        boolean rightBlocked = (a[i+1] < 0 && t + 1 >= -a[i+1]);
                        if (!rightBlocked) {
                            dinic.addEdge(node, rightNode, Long.MAX_VALUE / 2);
                        }
                    }
                }

                // People appear at time t+1 from entrance doors
                if (a[i] > 0 && t >= 1 && t <= a[i]) {
                    dinic.addEdge(source, node, 1);
                }
            }
        }

        long result = dinic.maxFlow(source, sink);
        System.out.println(result);
    }
}

