import java.util.*;

/*
 * Evacuation Route
 *
 * Model:
 * - Corridor cells 0..W-1
 * - ai = 0 : exit
 * - ai < 0 : fire door, cell becomes unusable from time |ai| onward
 *            so a person may be in / enter that cell only at times < |ai|
 * - ai > 0 : one person appears at times 0..ai-1 in this cell, and each starts moving at time t+1
 *
 * A person starting from cell s at appearance time t0 can first be at cell s at time t0+1.
 * To reach an exit at cell e, shortest travel time is |s-e|, so arrival time is:
 *      t0 + 1 + |s-e|
 * Feasibility also requires every traversed cell x to be usable at the time the person is there.
 * Along a monotone shortest path, cell x is reached at time t0 + 1 + dist(s,x).
 * Therefore:
 *      t0 + 1 + dist(s,x) < blockTime[x]   for every fire cell x on the path
 * where blockTime[x] = |a[x]|.
 *
 * This gives:
 *      t0 <= blockTime[x] - 2 - dist(s,x)
 * for each fire cell x on the path, and also
 *      t0 <= ai[s]-1
 *
 * For a fixed start s and direction, the number of people that can use some exit in that direction
 * equals max over exits e in that direction of:
 *      max(0, min(ai[s]-1, min over fire x on path(s,e) of (block[x]-2-dist(s,x))) + 1)
 *
 * As we extend farther in one direction, the fire constraint bound only decreases.
 * Thus for each s, the best exit on the left is simply the first exit encountered before any worse
 * prefix makes impossible; same with right. We can scan and maintain prefix minima.
 *
 * Let leftCap[s] = maximum number of people from s that can reach some exit to the left.
 * Scan left->right? Easier:
 *   For each s, among exits to the left, need the maximum feasible t0 count.
 *   Define while scanning from left to right:
 *      bestExitSeen = whether an exit exists in prefix
 *      minVal = min over fire cells x since beginning? For start-dependent expression:
 *              block[x] - 2 + x   when moving left from s to exit e<=s and x in [e,s]
 *      because dist(s,x)=s-x, so bound = block[x]-2-(s-x) = (block[x]-2+x) - s
 *   For a chosen exit e, path includes fire cells in [e,s]. For any exit to left, constraint is
 *   minimum over fire cells from that exit to s. To maximize feasibility, choose the nearest/rightmost
 *   exit among those that minimize included fires. This can be handled by segmenting between exits:
 *   for start s, best left exit is the rightmost exit <= s, because any farther-left exit includes
 *   a superset of cells and thus no better constraints and longer path. Same for right: nearest exit.
 *
 * Therefore each start cell only needs nearest exit on left and nearest exit on right.
 *
 * For nearest left exit L:
 *   need all fire cells x in [L,s]:
 *      t0 <= (block[x]-2+x) - s
 *   So bound = min_{x in [L,s], fire}(block[x]-2+x) - s
 *   If no fire cells, bound = +inf.
 * Similar for nearest right exit R:
 *      t0 <= (block[x]-2-x) + s   for x in [s,R]
 *
 * We precompute nearest exits and range minima over transformed fire values.
 *
 * Answer = sum over positive ai cells of
 *          max( leftCount, rightCount )
 * because each person chooses one side independently, exits have unlimited capacity.
 */
public class Main {
    static final long INF = (long) 4e18;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int W;
        try {
            W = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        long[] a = new long[W];
        for (int i = 0; i < W; i++) a[i] = fs.nextLong();

        int[] nearestLeftExit = new int[W];
        int[] nearestRightExit = new int[W];
        Arrays.fill(nearestLeftExit, -1);
        Arrays.fill(nearestRightExit, -1);

        int last = -1;
        for (int i = 0; i < W; i++) {
            if (a[i] == 0) last = i;
            nearestLeftExit[i] = last;
        }
        last = -1;
        for (int i = W - 1; i >= 0; i--) {
            if (a[i] == 0) last = i;
            nearestRightExit[i] = last;
        }

        long[] prefMinLeftVal = new long[W];
        long cur = INF;
        for (int i = 0; i < W; i++) {
            if (a[i] < 0) {
                long block = -a[i];
                cur = Math.min(cur, block - 2L + i);
            }
            prefMinLeftVal[i] = cur;
        }

        long[] sufMinRightVal = new long[W];
        cur = INF;
        for (int i = W - 1; i >= 0; i--) {
            if (a[i] < 0) {
                long block = -a[i];
                cur = Math.min(cur, block - 2L - i);
            }
            sufMinRightVal[i] = cur;
        }

        // To get range minima between nearest exit and s, reset minima at exits.
        long[] leftBoundAt = new long[W];   // min(block-2+x) over fire cells since nearest left exit to i
        long[] rightBoundAt = new long[W];  // min(block-2-x) over fire cells from i to nearest right exit

        cur = INF;
        for (int i = 0; i < W; i++) {
            if (a[i] == 0) cur = INF;
            if (a[i] < 0) {
                long block = -a[i];
                cur = Math.min(cur, block - 2L + i);
            }
            leftBoundAt[i] = cur;
        }

        cur = INF;
        for (int i = W - 1; i >= 0; i--) {
            if (a[i] == 0) cur = INF;
            if (a[i] < 0) {
                long block = -a[i];
                cur = Math.min(cur, block - 2L - i);
            }
            rightBoundAt[i] = cur;
        }

        long ans = 0;

        for (int s = 0; s < W; s++) {
            if (a[s] <= 0) continue;
            long people = a[s];

            long best = 0;

            int L = nearestLeftExit[s];
            if (L != -1) {
                long bound = people - 1; // t0 <= people-1
                long fireBound = leftBoundAt[s];
                if (fireBound != INF) bound = Math.min(bound, fireBound - s);
                if (bound >= 0) best = Math.max(best, bound + 1);
            }

            int R = nearestRightExit[s];
            if (R != -1) {
                long bound = people - 1;
                long fireBound = rightBoundAt[s];
                if (fireBound != INF) bound = Math.min(bound, fireBound + s);
                if (bound >= 0) best = Math.max(best, bound + 1);
            }

            ans += best;
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) throw new EOFException();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
