int head[MAXN], nxt[MAXE*2], to[MAXE*2], cap[MAXE*2], ecnt;
int level[MAXN], iter[MAXN];
int queue[MAXN];

void init(int n) { memset(head, -1, sizeof(int)*(n+1)); ecnt=0; }
void add(int u, int v, int c) {
    to[ecnt]=v; cap[ecnt]=c; nxt[ecnt]=head[u]; head[u]=ecnt++;
    to[ecnt]=u; cap[ecnt]=0; nxt[ecnt]=head[v]; head[v]=ecnt++;
}
int bfs(int s, int t, int n) {
    memset(level,-1,sizeof(int)*(n+1));
    int front=0,back=0; queue[back++]=s; level[s]=0;
    while(front<back){int u=queue[front++];for(int e=head[u];e!=-1;e=nxt[e])if(cap[e]>0&&level[to[e]]==-1){level[to[e]]=level[u]+1;queue[back++]=to[e];}}
    return level[t]>=0;
}
int dfs(int u, int t, int f) {
    if(u==t)return f;
    for(;iter[u]!=-1;iter[u]=nxt[iter[u]]){int e=iter[u];if(cap[e]>0&&level[to[e]]==level[u]+1){int d=dfs(to[e],t,f<cap[e]?f:cap[e]);if(d>0){cap[e]-=d;cap[e^1]+=d;return d;}}}
    return 0;
}
int maxflow(int s, int t, int n) {
    int flow=0; while(bfs(s,t,n)){memcpy(iter,head,sizeof(int)*(n+1));int d;while((d=dfs(s,t,1<<30))>0)flow+=d;} return flow;
}

