            int s_max = M[i] - dist[i]; // maximum start time s (first move time) such that can reach exit
            // s = t+1, so t+1 < s_max => t <= s_max - 2
            int max_t = s_max - 2;
            if (max_t < 0) continue;
            int can_leave = (a[i] < max_t + 1) ? a[i] : (max_t + 1);
            total += can_leave;
        }
    }

    printf("%lld\n", total);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

static ll minll(ll a, ll b) { return a < b ? a : b; }

int main(void) {
    int W;
    if (scanf("%d", &W) != 1) return 0;

    int *a = (int *)malloc(sizeof(int) * W);
    for (int i = 0; i < W; i++) scanf("%d", &a[i]);

    /* nearest exit on the left/right */
    int *leftExit = (int *)malloc(sizeof(int) * W);
    int *rightExit = (int *)malloc(sizeof(int) * W);

    int last = -1;
    for (int i = 0; i < W; i++) {
        if (a[i] == 0) last = i;
        leftExit[i] = last;
    }
    last = -1;
    for (int i = W - 1; i >= 0; i--) {
        if (a[i] == 0) last = i;
        rightExit[i] = last;
    }

    /*
      For each direction, maintain the minimum blocking deadline among
      fire doors on the path.
      Moving onto / through a fire door at position j is possible only before time |a[j]|.
      If a person starts from i at time s and needs d steps, arrival requires s + d < deadline.
    */

    const ll INF = (1LL << 60);

    ll *leftMinFire = (ll *)malloc(sizeof(ll) * W);
    ll *rightMinFire = (ll *)malloc(sizeof(ll) * W);

    ll cur = INF;
    for (int i = 0; i < W; i++) {
        if (a[i] < 0) cur = minll(cur, (ll)(-a[i]));
        leftMinFire[i] = cur;
    }
    cur = INF;
    for (int i = W - 1; i >= 0; i--) {
        if (a[i] < 0) cur = minll(cur, (ll)(-a[i]));
        rightMinFire[i] = cur;
    }

    ll ans = 0;

    for (int i = 0; i < W; i++) {
        if (a[i] <= 0) continue; /* no source people here */

        ll best = 0;

        /* Go left to nearest exit */
        if (leftExit[i] != -1) {
            int e = leftExit[i];
            int dist = i - e;
            /*
              Path includes cells e..i. Any fire door on this segment restricts start time:
              start_time + dist < min_deadline_on_segment
              start_time in [0, a[i)-1]
            */
            ll deadline = leftMinFire[i];
            if (e > 0 && leftMinFire[e - 1] < deadline) {
                /* remove fires strictly before e by recomputing segment minimum */
                deadline = INF;
                for (int k = e; k <= i; k++) if (a[k] < 0) deadline = minll(deadline, (ll)(-a[k]));
            }
            ll cnt;
            if (deadline == INF) cnt = a[i];
            else {
                ll limit = deadline - dist; /* start_time < limit */
                if (limit <= 0) cnt = 0;
                else cnt = minll((ll)a[i], limit);
            }
            if (cnt > best) best = cnt;
        }

        /* Go right to nearest exit */
        if (rightExit[i] != -1) {
            int e = rightExit[i];
            int dist = e - i;
            ll deadline = rightMinFire[i];
            if (e + 1 < W && rightMinFire[e + 1] < deadline) {
                deadline = INF;
                for (int k = i; k <= e; k++) if (a[k] < 0) deadline = minll(deadline, (ll)(-a[k]));
            }
            ll cnt;
            if (deadline == INF) cnt = a[i];
            else {
                ll limit = deadline - dist; /* start_time < limit */
                if (limit <= 0) cnt = 0;
                else cnt = minll((ll)a[i], limit);
            }
            if (cnt > best) best = cnt;
        }

        ans += best;
    }

    printf("%lld\n", ans);

    free(a);
    free(leftExit);
    free(rightExit);
    free(leftMinFire);
    free(rightMinFire);
    return 0;
}
